{
  "qid": "0023_lexus_L2_01",
  "sample_id": "0023",
  "gen_prompt": "写实高端商业汽车摄影：一辆雷克萨斯豪华轿车停在现代美术馆入口前，采用低机位正面三分之四近景，车头朝向镜头，前脸中央区域无遮挡且细节清晰。车身为珍珠白色，停在雨后深灰色石材地面上；画面右后方设置两根暖光立柱，背景是暮蓝色玻璃幕墙。地面保留柔和倒影，车辆处于静止状态。画面中只出现这一辆车，不出现人物或其他车辆，横向构图，写实摄影风格。",
  "invocation": "L2",
  "knowledge_dim": "汽车品牌识别、品牌徽记结构与乘用车产品呈现",
  "fidelity_checks": [
    {
      "check": "车头品牌标识呈现为外部封闭环框与内部单一字母造型共同构成的雷克萨斯标识，而非缺少其中任一部分的普通装饰件。",
      "lens": "K1",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "1",
          "3"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "标识完全缺失；只有空环或孤立字母；外框与内部字形彼此分离成无关装饰；或整体被画成不含该组合结构的其他构件。",
        "tier_1": "清楚呈现封闭外框包围单一字母造型的完整组合，整体可识别为雷克萨斯车标。",
        "tier_2": "在满足 Pass 的基础上，外框、内部字形及两者间留白关系均刻画精确，组合轮廓在车头曲面和透视下仍高度清楚、接近真实品牌徽记的精细度。"
      },
      "variants_used": "",
      "visibility_requirement": "题面已要求车头前脸中央区域无遮挡且清晰；若该区域被裁切、遮挡、过小或模糊到无法核验组合结构，本条按 0 处理。"
    },
    {
      "check": "标识外轮廓构成连续、完整闭合的环形边界，不得存在断口或退化为实心底板。",
      "lens": "K1",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "2"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "外轮廓出现明显断口、缺段或无法闭合；被画成实心几何底板；或外框部件缺失。",
        "tier_1": "外轮廓为连续且明确闭合的环框，内部区域与环框边界可清楚区分。",
        "tier_2": "在满足 Pass 的基础上，闭合环框厚度、内外边缘和转折连续性处理精确，在反光与车头透视下仍无粘连或断裂。"
      },
      "variants_used": "",
      "visibility_requirement": "必须能连续追踪外轮廓一周；若因遮挡、裁切或模糊无法确认是否闭合，按 0 处理。"
    },
    {
      "check": "车标外框为横向展开的椭圆轮廓，其可见宽度明确大于高度。",
      "lens": "K1",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "2"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "外框被画成正圆、纵向椭圆，或宽高关系颠倒；透视不足以解释其明显错误取向。",
        "tier_1": "外框清楚呈横置椭圆，宽度大于高度；允许符合正面三分之四视角的合理透视压缩。",
        "tier_2": "在满足 Pass 的基础上，横向比例自然准确，且椭圆轮廓与车头安装面的透视关系精细一致。"
      },
      "variants_used": "",
      "visibility_requirement": "需看到外框整体宽高关系；题面视角允许轻微透视变形，但若外框不完整或小到无法判断取向，按 0 处理。"
    },
    {
      "check": "标识外框保持椭圆环这一形态，不得替换为盾牌、方框、三角框或其他类别的外框。",
      "lens": "K1",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "2"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "外框呈盾形、矩形、方形、三角形、多边形或其他明显非椭圆的轮廓；或多出改变外框类别的尖角和附属结构。",
        "tier_1": "外框类别明确为平滑的椭圆环，没有改变其类别的尖角、直边或附加框体。",
        "tier_2": "在满足 Pass 的基础上，椭圆曲率连续匀整，内外轮廓精细平行，并在车身反射和透视下保持可信形态。"
      },
      "variants_used": "",
      "visibility_requirement": "外框四周须基本可见；若局部高光存在但整体轮廓仍可追踪则正常判定，若不可辨认则按 0 处理。"
    },
    {
      "check": "车头标识不得被画成丰田三椭圆结构、奔驰三叉星、宝马蓝白圆章、奥迪四环或其他汽车品牌的徽记拓扑。",
      "lens": "K1",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "7"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "标识明显采用三椭圆、三叉星、蓝白分区圆章、四个相连圆环等其他品牌结构，或完全属于另一汽车品牌的可识别形态。",
        "tier_1": "标识结构属于雷克萨斯体系，未混入其他汽车品牌的核心构形。",
        "tier_2": "在满足 Pass 的基础上，品牌结构辨识度极高，微小尺度下仍能凭准确轮廓和内部布局排除相近或混合品牌形态。"
      },
      "variants_used": "",
      "visibility_requirement": "车头标识须足够清楚以排除其他品牌拓扑；若被替换、隐藏或模糊到无法归类，按 0 处理。"
    },
    {
      "check": "椭圆环内部清楚呈现可识别的字母“L”，且整个字形均位于外框轮廓以内。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "3"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "内部字形缺失、乱码或无法识别为“L”；字形被误写为其他字母；或字形明显穿出、越过外框。",
        "tier_1": "内部字形可明确逐字识别为“L”，且字形整体完整地收纳在外框以内。",
        "tier_2": "在满足 Pass 的基础上，“L”的笔画轮廓、位置和与外框的间距均高度精确，即使受金属反光与透视影响仍可无歧义识别。"
      },
      "variants_used": "",
      "visibility_requirement": "必须能辨认内部字符及其与外框的边界关系；若字符太小、过曝、反光糊连或被遮挡而无法抄录，按 0 处理。"
    },
    {
      "check": "标识内部除单个字母“L”外不得出现额外字母或数字。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "4"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "内部出现第二个字母、品牌全称、数字、乱码或疑似编造字符；或将“L”重复成多个字符。",
        "tier_1": "内部只有一个可识别的“L”，没有任何额外字母、数字或乱码。",
        "tier_2": "在满足 Pass 的基础上，内部字符区边界极为干净，反光、纹理和接缝均未形成任何类似额外字符的伪字形。"
      },
      "variants_used": "",
      "visibility_requirement": "内部区域需清楚到可以逐项检查字符；若细节不足以排除额外字符，按 0 处理。"
    },
    {
      "check": "标识内部除规定的“L”字形外，不得增添星形、十字、箭头、环组或其他独立图形符号。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "4"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "内部出现星形、十字、箭头、额外圆环、纹章图案或其他独立符号；或装饰线被处理成与“L”并列的第二图形。",
        "tier_1": "内部视觉内容仅为规定的“L”字形，没有额外独立图形符号。",
        "tier_2": "在满足 Pass 的基础上，字形与背景、反光和安装结构分离清晰，内部空间简洁准确且无任何伪符号干扰。"
      },
      "variants_used": "",
      "visibility_requirement": "须能检查内部全部可见区域；正常金属高光不视为符号，但若画面模糊到无法区分高光与附加图形，按 0 处理。"
    },
    {
      "check": "内部字母“L”采用无衬线的几何化造型，不得呈衬线体、花体或手写体。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "5"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "字形带明显衬线、卷曲花饰或手写笔触；笔画被画成书法式、草写式形态；或字形风格与几何化无衬线结构明显相悖。",
        "tier_1": "“L”为简洁、硬朗且可辨认的无衬线几何字形，没有花体、手写或衬线特征。",
        "tier_2": "在满足 Pass 的基础上，几何笔画的角度、粗细、端点与连接处理高度精确，具有真实车标金属字形的清晰雕塑感。"
      },
      "variants_used": "",
      "visibility_requirement": "字形边缘必须足够清楚以判断有无衬线和装饰笔触；若因尺度或模糊无法判断字体结构，按 0 处理。"
    },
    {
      "check": "内部“L”保持正确左右方向，不得水平镜像为竖笔在右、底部笔画向左伸展的反向字形。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "6"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "字形被水平镜像，呈竖笔位于右侧且底部笔画朝左的反向“L”；字形方向混乱；或无法辨认为正常方向的“L”。",
        "tier_1": "“L”方向正确，竖向主体位于左侧，底部笔画向右延伸；合理透视变形不改变其左右关系。",
        "tier_2": "在满足 Pass 的基础上，正确方向在车头三分之四透视、曲面安装与反射条件下仍表达精准，笔画朝向毫无歧义。"
      },
      "variants_used": "",
      "visibility_requirement": "需看清字形左右关系；题面所要求的真实车头视图不属于镜面反射画面，若主体标识方向不可辨或实际反向，按 0 处理。"
    }
  ],
  "leak_check": {
    "对照表": [
      {
        "constraint_ref": "1",
        "题面中是否出现": "无"
      },
      {
